package com.vandorlabs.neoforge.screen;

import com.google.gson.*;
import com.vandorlabs.neoforge.ModernHousingTags;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import com.vandorlabs.neoforge.shape.PanelPlayback;
import com.vandorlabs.persistence.FrameSettings;
import com.vandorlabs.screen.ScreenFamily;
import java.nio.file.*;
import java.util.*;
import net.minecraft.nbt.CompoundTag;

/** Compare replacement role/material routing with the real released renderer's nonempty draw sequence. */
public final class ScreenRenderPlanChecks {
 private static int checks;private static boolean validActivation;private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Screen render plan: "+message);}
 private static NativeScreenEntity.Visual visual(ScreenFamily family,int mode,int variant,boolean framed,boolean rows){var catalog=NativeScreenCatalog.INSTANCE;var tag=NativeScreenFactory.choices(family,catalog,catalog.defaultHousing(),catalog.defaultFrame());tag.putInt("displayMode",mode);tag.putBoolean("smallInput",variant==1);tag.putInt("wallPosition",variant==1?2:0);tag.putBoolean("CeilingMounted",variant==2);tag.putInt("CeilingPosition",1);tag.putBoolean("FrameTile",true);tag.putInt("FrameFront",framed?catalog.sourceChoice("frames/frames-door-window/lights-cyan-1"):-1);tag.putInt("SurfaceTextureLayout",variant);
  if(variant==1){int custom=catalog.sourceChoice("console_inputs/console_controls_biology_controls_static");tag.putInt("housingTexture",com.vandorlabs.tiles.HousingFinishCatalog.legacyCount()-1);tag.putInt("PrimarySurfaceTexture",custom);tag.putInt("SecondarySurfaceTexture",custom);tag.putBoolean("DisplaySplit",true);tag.putBoolean("DisplayFit",true);tag.putInt("DisplaySplitTop",custom);}
  if(variant==2){var activation=new CompoundTag();activation.putInt("Mode",2);activation.putIntArray("Textures",rows?new int[]{141,141,141,141}:new int[]{-1,-1,-1,-1});activation.putIntArray("Playback",new int[]{0,1,2,mode});activation.putIntArray("Speeds",rows||validActivation?new int[]{0,1,2,1}:new int[]{0,1,2,3});tag.put("DisplayActivation",activation);tag.putInt("ChannelLevel",15);}
  tag=NativeScreenArtworkMigration.normalize(tag,catalog);var settings=NativeScreenSettings.read(tag,catalog);var frames=FrameSettings.read(new ModernHousingTags(tag),catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var controls=List.of(new NativeScreenControls(rows,"ROWS",List.of()),new NativeScreenControls(false,"ROWS",List.of()));var appearance=NativeScreenAppearance.of(family,settings,frames,controls,0,catalog);return new NativeScreenEntity.Visual(family,settings,frames,PanelPlayback.DEFAULT,controls,settings.channelLevel(),0,false,1,appearance);
 }
 private static boolean glowing(int choice){if(choice<0)return false;var entry=ModernFinishCatalog.option(choice);return entry!=null&&entry.frame()!=null&&entry.frame().light()>0;}
 private static void lighting(NativeScreenRenderPlan plan,JsonObject reference){int owner=reference.get("owner").getAsInt(),current=owner;List<Integer> actual=new ArrayList<>();for(var body:plan.geometry.bodies){if(body.mesh.quads.length>0)actual.add(owner);if(body.mesh.triangles.length>0)actual.add(owner);}boolean glow=glowing(plan.visual.frames().front)||glowing(plan.visual.frames().interior)||glowing(plan.visual.frames().exteriorChoice());for(var surface:plan.surfaces){boolean frame=surface.geometry().frame&&plan.visual.frames().front>=0&&!plan.visual.frames().bare;if(frame&&surface.frameBefore())actual.add(glow?(current&0xffff0000)|240:current);for(var fragment:surface.fragments())if(fragment.binding()!=NativeScreenRenderPlan.Binding.NONE){current=switch(fragment.light()){case OWNER->owner;case FULL->0xF000F0;case KEEP->current;};actual.add(current);}if(frame&&!surface.frameBefore())actual.add(glow?(current&0xffff0000)|240:current);}var expected=reference.getAsJsonArray("lights");need(actual.size()==expected.size(),"Source light draw coverage");for(int i=0;i<actual.size();i++)need(actual.get(i)==expected.get(i).getAsInt(),"actual Source packed light "+plan.visual.family()+" draw="+i+" expected="+expected.get(i)+" actual="+actual.get(i));}
 private record Draw(int mode,int count,NativeScreenRenderPlan.Fragment fragment){}
 public static void main(String[] args)throws Exception{validActivation=args.length>2&&Boolean.parseBoolean(args[2]);var reference=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonObject();int profiles=0;Map<String,JsonObject> lights=new HashMap<>();try(var stream=new java.util.zip.GZIPInputStream(Files.newInputStream(Path.of(args[1])));var reader=new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){for(var value:JsonParser.parseReader(reader).getAsJsonObject().getAsJsonArray("cases")){var row=value.getAsJsonObject();lights.put(row.get("id").getAsString()+"/"+row.get("mode")+"/"+row.get("variant")+"/"+row.get("frame"),row);}}
  for(var value:reference.getAsJsonArray("requests")){var row=value.getAsJsonObject();var family=ScreenFamily.fromId(row.get("id").getAsString());var visual=visual(family,row.get("mode").getAsInt(),row.get("variant").getAsInt(),row.get("frame").getAsBoolean(),false);var plan=NativeScreenRenderPlan.of(visual,family.decode(2));List<Draw> actual=new ArrayList<>();for(var body:plan.geometry.bodies){if(body.mesh.quads.length>0)actual.add(new Draw(7,body.mesh.quads.length*4,null));if(body.mesh.triangles.length>0)actual.add(new Draw(4,body.mesh.triangles.length*3,null));}
   for(var surface:plan.surfaces){boolean frame=surface.geometry().frame&&visual.frames().front>=0&&!visual.frames().bare;if(frame&&surface.frameBefore())actual.add(new Draw(7,32,null));for(var fragment:surface.fragments())if(fragment.binding()!=NativeScreenRenderPlan.Binding.NONE)actual.add(new Draw(7,4,fragment));if(frame&&!surface.frameBefore())actual.add(new Draw(7,32,null));}
   List<JsonObject> expected=new ArrayList<>();for(var draw:row.getAsJsonArray("draws"))if(draw.getAsJsonObject().get("vertexCount").getAsInt()>0)expected.add(draw.getAsJsonObject());need(actual.size()==expected.size(),"draw count "+family+" mode="+row.get("mode")+" variant="+row.get("variant")+" frame="+row.get("frame")+" expected="+expected.size()+" actual="+actual.size());
   for(int i=0;i<actual.size();i++){var draw=actual.get(i);var wanted=expected.get(i);need(draw.mode==wanted.get("mode").getAsInt()&&draw.count==wanted.get("vertexCount").getAsInt(),"source topology/order "+family+" draw="+i);String texture=wanted.get("texture").getAsString();var fragment=draw.fragment;if(fragment==null)need(texture.equals("minecraft:textures/atlas/blocks.png"),"housing/frame atlas");else switch(fragment.binding()){
    case ATLAS->need(texture.equals("minecraft:textures/atlas/blocks.png"),"literal/split atlas routing "+family);
    case OFF->need(texture.equals("vandorlabs:textures/blocks/screen_off.png"),"shared display Off");
    case INPUT->need(texture.equals(fragment.mode()==0?fragment.input().sourceOff():fragment.input().sourceStationary()),"builtin input binding");
    case DISPLAY->need(fragment.mode()==0?texture.equals("vandorlabs:textures/blocks/screen_off.png"):fragment.mode()==2?texture.startsWith("vandorlabs:compact_animation/"):texture.endsWith("_static.png"),"builtin/animated display routing "+family+" mode="+fragment.mode()+" texture="+texture);
    default->throw new AssertionError("Unexpected dynamic fixture binding "+fragment.binding());
   }}lighting(plan,lights.get(row.get("id").getAsString()+"/"+row.get("mode")+"/"+row.get("variant")+"/"+row.get("frame")));profiles++;
  }
  for(var family:List.of(ScreenFamily.SCREEN,ScreenFamily.CONSOLE,ScreenFamily.DIAGONAL,ScreenFamily.HALF_DIAGONAL)){var hidden=visual(family,1,2,true,true);need(hidden.appearance().surface(0)>=0,"modern override hides rows");var plan=NativeScreenRenderPlan.of(hidden,family.decode(2));var main=plan.surfaces.stream().filter(s->s.geometry().slot==0).findFirst().orElseThrow();need(main.fragments().getFirst().binding()==NativeScreenRenderPlan.Binding.NONE,"released enabled-row early return remains frame-only");}
  int chipProfiles=0;for(var family:List.of(ScreenFamily.CONSOLE,ScreenFamily.HALF_CONSOLE,ScreenFamily.HALF_DIAGONAL))for(int facing=0;facing<6;facing++)for(int upper=0;upper<(family==ScreenFamily.HALF_DIAGONAL?2:1);upper++)for(int mode=0;mode<3;mode++)for(int variant=0;variant<3;variant++)for(boolean framed:new boolean[]{false,true}){var base=visual(family,mode,variant,framed,false);var tag=new CompoundTag();base.settings().write(tag);int chipSlot=family==ScreenFamily.HALF_CONSOLE?1:0;tag.putInt(chipSlot==0?"PrimarySurfaceTexture":"SecondarySurfaceTexture",-4);tag.remove("DisplayActivation");var settings=NativeScreenSettings.read(tag,NativeScreenCatalog.INSTANCE);var controls=List.of(new NativeScreenControls(variant==2&&chipSlot==1,"",List.of()),new NativeScreenControls(variant==2&&chipSlot==0&&family!=ScreenFamily.HALF_DIAGONAL,"",List.of()));var appearance=NativeScreenAppearance.of(family,settings,base.frames(),controls,0,NativeScreenCatalog.INSTANCE);var selected=new NativeScreenEntity.Visual(family,settings,base.frames(),base.glass(),controls,0,0,false,1,appearance);var plan=NativeScreenRenderPlan.of(selected,new com.vandorlabs.screen.ScreenFamily.State(facing,false,upper!=0,false));need(plan.chip,"raw selected chip survives appearance resolution");need(plan.geometry.bodies.size()==2,"selected chip body count");if(family==ScreenFamily.HALF_DIAGONAL)need(plan.geometry.bodies.getFirst().basePose,"front tray must use unscaled base pose");else{var deck=plan.surfaces.stream().filter(v->v.geometry().slot!=chipSlot).findFirst().orElseThrow();need(deck.geometry().reverseU&&!deck.geometry().frame,"deck retains reversed input UV without frame overlay");}chipProfiles++;}need(chipProfiles==432,"selected chip branch coverage");
  need(profiles==126,"released request coverage");System.out.println("Native Screen render plan PASS profiles="+profiles+" checks="+checks+" Source material/Off/static/animated/split/frame order and hidden-row early-return");
 }
}
